DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('v261_lot_action(uuid,uuid,int,text,jsonb)'::regprocedure) INTO d;
 d:=replace(d,$old$SELECT EXISTS(SELECT 1 FROM lot_work_history h WHERE h.allocation_id=doc AND h.action IN('WEIGH','SAMPLE-STAGE')) INTO facts;$old$,$new$SELECT EXISTS(SELECT 1 FROM lot_work_history h WHERE h.allocation_id=doc AND h.action IN('WEIGH','SAMPLE-STAGE')) OR EXISTS(SELECT 1 FROM inventory_events e JOIN allocation_items ai ON ai.bundle_id=e.bundle_id WHERE ai.allocation_id=doc AND e.event_type IN('MOVE','ADJUST_LOCATION') AND e.occurred_at>=a.created_at) INTO facts;$new$);EXECUTE d;END $$;
